static inline void id_table_add(s32 x, s32 y, s32 scale, s32 depth, s32 f08, s32 f0A, s32 f0C) {
    IdTableRecords *tbl = (IdTableRecords *)&id_table;
    s32 index;
    IdRecord *rec;

    __asm__ volatile("");
    FAKE_OPAQUE(tbl);
    index = tbl->count;

    if (index < 0x100) {
        tbl->count = index + 1;
        rec = &tbl->rec[index];
        rec->prev_id = tbl->id[0];
        tbl->id[0] = index;
        rec->field_00 = x;
        rec->field_02 = y;
        rec->field_04 = scale;
        rec->field_0E = depth;
        rec->field_08 = f08;
        rec->field_0A = f0A;
        rec->field_0C = f0C;
        rec->field_10 = 0;
    }
}

